ssize_t WritePSDChannels(const PSDInfo *psd_info, const ImageInfo *image_info, Image *image, Image *next_image, MagickOffsetType size_offset, MagickBooleanType separate) {
    ssize_t count = 0;
    MagickBooleanType status = MagickTrue;
    size_t length;
    MagickOffsetType offset;
    unsigned char *compact_pixels = NULL;
    size_t number_pixels;

    number_pixels = image->columns * image->rows;
    compact_pixels = (unsigned char *) AcquireMemory(number_pixels * sizeof(*compact_pixels));
    if (compact_pixels == (unsigned char *) NULL) {
        return 0;
    }

    if (next_image != (Image *) NULL) {
        switch (next_image->compression) {
            case RLECompression:
                if (AcquireRLECompressedData(next_image, compact_pixels, &length) == MagickFalse) {
                    status = MagickFalse;
                    break;
                }
                break;
            default:
                (void) memcpy(compact_pixels, image->pixels, number_pixels * sizeof(*compact_pixels));
                length = number_pixels;
                break;
        }
    }

    if (status != MagickFalse) {
        if (image->storage_class == PseudoClass) {
            if (image->colorspace == CMYKColorspace || image->colorspace == LabColorspace) {
                for (offset = 0; offset < (MagickOffsetType) number_pixels; offset++) {
                    compact_pixels[offset] = image->pixels[offset] * 255.0 / MaxMap;
                }
            }
            else {
                for (offset = 0; offset < (MagickOffsetType) number_pixels; offset++) {
                    compact_pixels[offset] = image->pixels[offset] * 255.0 / MaxMap;
                }
            }
        }

        if (separate != MagickFalse) {
            for (int i = 0; i < psd_info->channels; i++) {
                count += WritePSDChannel(image, image_info, compact_pixels, size_offset);
                size_offset += count;
            }
        }
        else {
            count = WritePSDChannel(image, image_info, compact_pixels, size_offset);
        }

        if (image->mask != (PixelMask *) NULL) {
            count += WritePSDMask(image, image_info, size_offset);
            size_offset += count;
        }
    }

    compact_pixels = (unsigned char *) RelinquishMemory(compact_pixels);
    return (count != 0 ? count : 0);
}

ssize_t WritePSDImageChannels(const PSDInfo *psd_info, const ImageInfo *image_info, Image *image, Image *next_image, MagickOffsetType size_offset, MagickBooleanType separate)
{
    MagickOffsetType
        offset = size_offset;

    register const Quantum
        *p;

    size_t
        number_pixels = GetImagePixelCount(image),
        y;

    ssize_t
        count = 0;

    if (next_image != (Image *) NULL)
    {
        if (next_image->compression == RLECompression)
        {
            /* Acquire compact pixel data if necessary */
            Quantum
                *compact_pixels = AcquireQuantumInfoPixels(image, next_image->image);
            if (compact_pixels == (Quantum *) NULL)
                return 0;

            for (y = 0; y < image->rows; y++)
            {
                p = compact_pixels + (y * image->columns * GetPixelChannels(image));
                count += WriteBlob(image, image->columns * GetPixelChannels(image), p);
                offset += image->columns * GetPixelChannels(image);
            }

            compact_pixels = DestroyQuantumPixels(compact_pixels);
            if (compact_pixels == (Quantum *) NULL)
                return 0;
        }
        else
        {
            for (y = 0; y < image->rows; y++)
            {
                p = GetVirtualScanline(image, y);
                if (image->colorspace == CMYKColorspace)
                {
                    count += WriteBlob(image, image->columns * 4, p);
                    offset += image->columns * 4;
                }
                else if (image->colorspace == RGBColorspace)
                {
                    count += WriteBlob(image, image->columns * 3, p);
                    offset += image->columns * 3;
                }
                else
                {
                    count += WriteBlob(image, image->columns * 1, p);
                    offset += image->columns * 1;
                }
            }
        }
    }

    if (separate != MagickFalse)
    {
        for (y = 0; y < image->rows; y++)
        {
            p = GetVirtualScanline(image, y);
            count += WriteBlob(image, image->columns * GetPixelChannels(image), p);
            offset += image->columns * GetPixelChannels(image);
        }
    }

    if (image->mask != (PixelInfo *) NULL)
    {
        for (y = 0; y < image->rows; y++)
        {
            p = GetVirtualScanline(image, y);
            count += WriteBlob(image, image->columns, p);
            offset += image->columns;
        }
    }

    return (ssize_t) (offset - size_offset);
}
